mapper.select:
SELECT bd.id AS id, bd.customer_id AS customerId, c.customer_name AS customerName, c.customer_sex AS customerSex, bd.bed_details AS bedDetails, bd.start_date AS startDate, bd.end_date AS endDate FROM beddetails bd LEFT JOIN customer c ON c.id = bd.customer_id WHERE bd.is_deleted = #{isDeleted}
AND c.customer_name LIKE CONCAT('%', #{customerName}, '%')
AND bd.start_date >= #{startDate}
ORDER BY bd.start_date DESC, bd.id DESC
